var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{errors:[],newTemplateText:null,templates:[]},methods:{getData(){const a=window.location.origin+"/dashboard/buttons/data";axios.get(a).then(a=>{this.templates=a.data}).catch(a=>{console.log(a)})},addNewTemplate(){if(!this.newTemplateText)this.errors.push("Kh\xF4ng \u0111\u01B0\u1EE3c \u0111\u1EC3 tr\u1ED1ng!");else{const a=window.location.origin+"/dashboard/buttons";axios.post(a,{name:this.newTemplateText,u_name:this.newTemplateText.replace(/\s+/g,"").toLowerCase(),val:[{stype:"postback",title:"",block:""}]}).then(a=>{this.errors=[],this.newTemplateText=null,this.templates=a.data}).catch(a=>{console.log(a)})}},deleteTemplate(a,b){const c=window.location.origin+"/dashboard/buttons/"+b;axios.delete(c).then(b=>{this.templates.splice(a,1),this.$notify({group:"notification",type:b.data.status,title:b.data.title,text:b.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},updateTemplate(a,b){const c=window.location.origin+"/dashboard/buttons/"+b;axios.post(c,{name:this.templates[a].name,u_name:this.templates[a].u_name,val:this.templates[a].val}).then(a=>{this.$notify({group:"notification",type:a.data.status,title:a.data.title,text:a.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},addNewButton(a,b){this.templates[a].val.push({stype:"postback",title:"",block:""}),this.updateTemplate(a,b)},deleteButton(a,b,c){this.templates[a].val.splice(b,1),this.updateTemplate(a,c)}},created(){this.getData()}});